		/**
		 * Returns a new populated Contract
		 * 
		 * @return Contract
		 */
		protected Contract generateNewEntity() {
			Contract entity = new Contract( null,  org.apache.commons.lang3.RandomStringUtils.randomAlphanumeric(16),   new Date(),   new Date(),  new URL(),  null,  new HashSet<>(),  new HashSet<>(),  null,  ContractStatus.values()[0] );
			
			return( entity );
		}

